using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;

public class YapiPane {
 public Grid View;List<YapiProfile> profiles;YapiProfile current;List<ApiEntry> entries=new List<ApiEntry>();bool loading;
 T Get<T>(string name) where T:class{return View.FindName(name) as T;}
 string Read(string name){return Get<TextBox>(name).Text.Trim();}
 void Write(string name,string value){Get<TextBox>(name).Text=value;}
 void Log(string text){View.Dispatcher.Invoke(new Action(()=>{Get<TextBox>("Log").AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);Get<TextBox>("Log").ScrollToEnd();}));}
 public YapiPane(){using(var stream=typeof(YapiPane).Assembly.GetManifestResourceStream("Yapi.xaml"))View=(Grid)XamlReader.Load(stream);profiles=YapiCache.Load();Get<ComboBox>("History").SelectionChanged+=(s,e)=>{if(!loading&&Get<ComboBox>("History").SelectedItem!=null)Choose((YapiProfile)Get<ComboBox>("History").SelectedItem);};Get<DataGrid>("Apis").SelectionChanged+=(s,e)=>{var item=Get<DataGrid>("Apis").SelectedItem as ApiEntry;if(item!=null)Write("Preview",item.Source+Environment.NewLine+item.Warning+Environment.NewLine+Json.Parse(JavaScanner.Serializer().Serialize(item.Payload)).Print(true));};
  Hook("New",()=>{current=new YapiProfile();Choose(current);return Task.FromResult(0);});Hook("SaveProfile",()=>{Capture();Save();Log("配置已加密保存，下次可直接选择。");return Task.FromResult(0);});Hook("Connect",async()=>{Capture();await Connect();Save();});Hook("Scan",async()=>{Capture();await Scan();Save();});Hook("Upload",async()=>{Capture();RememberSelection();Save();await Upload();});Hook("QuickUpload",async()=>{Capture();var selected=current.SelectedKeys.ToArray();if(selected.Length==0)throw new Exception("请先扫描并勾选一次接口，保存配置后即可快速上传。");await Connect();await Scan();foreach(var entry in entries)entry.Selected=selected.Contains(entry.Key)&&entry.Warning.Length==0;Get<DataGrid>("Apis").Items.Refresh();await Upload();});Hook("SelectSafe",()=>{foreach(var entry in entries)entry.Selected=entry.Warning.Length==0;Get<DataGrid>("Apis").Items.Refresh();return Task.FromResult(0);});Refresh();if(profiles.Count>0){Get<ComboBox>("History").SelectedIndex=0;}else Choose(new YapiProfile());}
 void Hook(string name,Func<Task> action){Get<Button>(name).Click+=async(s,e)=>{View.IsEnabled=false;try{await action();}catch(Exception ex){Log(ex.Message);MessageBox.Show(ex.Message,"YApi 导入",MessageBoxButton.OK,MessageBoxImage.Warning);}finally{View.IsEnabled=true;}};}
 void Refresh(){loading=true;Get<ComboBox>("History").ItemsSource=null;Get<ComboBox>("History").ItemsSource=profiles;Get<ComboBox>("History").SelectedItem=current;loading=false;}
 void Choose(YapiProfile profile){current=profile;loading=true;Write("ProfileName",profile.Name);Write("ScanDirectory",profile.ScanDirectory);Write("SourceRoot",profile.SourceRoot);Write("Server",profile.Server);try{Get<PasswordBox>("Token").Password=profile.Token();}catch{Get<PasswordBox>("Token").Password="";Log("此配置的 Token 无法解密，请重新填写。");}Get<CheckBox>("UpdateExisting").IsChecked=profile.UpdateExisting;Get<ComboBox>("Category").ItemsSource=profile.CategoryId>0?new[]{new YapiCategory{Id=profile.CategoryId,Name="已保存分类 #"+profile.CategoryId}}:null;Get<ComboBox>("Category").SelectedIndex=0;Get<TextBlock>("ProjectInfo").Text=profile.ProjectId>0?profile.ProjectName+" (#"+profile.ProjectId+")":"未连接";entries.Clear();Get<DataGrid>("Apis").ItemsSource=null;Write("Preview","");Get<TextBlock>("Count").Text="等待扫描";loading=false;if(profile.LastUpload.Length>0)Log("上次上传："+profile.LastUpload+"，"+profile.LastResult);}
 void Capture(){if(current==null)current=new YapiProfile();string oldToken="";try{oldToken=current.Token();}catch{}bool sourceChanged=current.ScanDirectory!=Read("ScanDirectory").TrimEnd('\\')||current.SourceRoot!=Read("SourceRoot").TrimEnd('\\');bool identityChanged=current.Server!=Read("Server")||oldToken!=Get<PasswordBox>("Token").Password;current.Name=Read("ProfileName");current.ScanDirectory=Read("ScanDirectory").TrimEnd('\\');current.SourceRoot=Read("SourceRoot").TrimEnd('\\');current.Server=Read("Server").TrimEnd('/');current.SetToken(Get<PasswordBox>("Token").Password);current.UpdateExisting=Get<CheckBox>("UpdateExisting").IsChecked==true;var cat=Get<ComboBox>("Category").SelectedItem as YapiCategory;if(cat!=null)current.CategoryId=cat.Id;if(identityChanged){current.ProjectId=0;current.CategoryId=0;}if(sourceChanged){entries.Clear();Get<DataGrid>("Apis").ItemsSource=null;current.SelectedKeys.Clear();Write("Preview","");}if(current.Name.Length==0)throw new Exception("请填写配置名称");}
 void RememberSelection(){Get<DataGrid>("Apis").CommitEdit(DataGridEditingUnit.Cell,true);Get<DataGrid>("Apis").CommitEdit(DataGridEditingUnit.Row,true);if(entries.Count>0)current.SelectedKeys=entries.Where(x=>x.Selected).Select(x=>x.Key).ToList();}
 void Save(){if(entries.Count>0)RememberSelection();if(!profiles.Any(p=>p.Id==current.Id))profiles.Add(current);YapiCache.Save(profiles);Refresh();}
 async Task Connect(){var client=new YapiClient(current);var p=await Task.Run(()=>client.Project());current.ProjectId=Convert.ToInt32(p["_id"]);current.ProjectName=Convert.ToString(p["name"]);var cats=await Task.Run(()=>client.Categories(current.ProjectId));Get<ComboBox>("Category").ItemsSource=cats;Get<ComboBox>("Category").SelectedItem=cats.FirstOrDefault(x=>x.Id==current.CategoryId)??cats.FirstOrDefault();var chosen=Get<ComboBox>("Category").SelectedItem as YapiCategory;if(chosen!=null)current.CategoryId=chosen.Id;Get<TextBlock>("ProjectInfo").Text=current.ProjectName+" (#"+current.ProjectId+")";Log("连接成功："+current.ProjectName);}
 async Task Scan(){if(!Directory.Exists(current.ScanDirectory)||!Directory.Exists(current.SourceRoot))throw new Exception("扫描目录或类型解析根目录不存在");string scan=Path.GetFullPath(current.ScanDirectory),root=Path.GetFullPath(current.SourceRoot);if(!scan.Equals(root,StringComparison.OrdinalIgnoreCase)&&!scan.StartsWith(root.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new Exception("扫描目录必须位于类型解析根目录内");Log("正在解析 Controller 和引用类型…");entries=await Task.Run(()=>new JavaScanner(root).Scan(scan));if(current.SelectedKeys.Count>0)foreach(var entry in entries)entry.Selected=current.SelectedKeys.Contains(entry.Key);Get<DataGrid>("Apis").ItemsSource=entries;Get<TextBlock>("Count").Text=entries.Count+" 个接口，"+entries.Count(x=>x.Warning.Length>0)+" 个需确认";Log("扫描完成："+entries.Count+" 个接口。警告项默认不勾选，请预览后处理。");}
 async Task Upload(){var selected=entries.Where(x=>x.Selected).ToList();if(selected.Count==0)throw new Exception("没有勾选待上传接口");if(selected.Any(x=>x.Method=="待确认"||x.Path.Contains("\"")||x.Method.Contains("{")))throw new Exception("所选接口存在未明确的方法或路径，请先排除这些接口。");if(current.ProjectId<=0)await Connect();if(current.CategoryId<=0)throw new Exception("请选择新接口所属分类");var client=new YapiClient(current);var existing=await Task.Run(()=>client.Existing(current.ProjectId));int success=0,failed=0,skipped=0;foreach(var entry in selected){try{entry.Result=await Task.Run(()=>client.Upload(entry,current,existing));if(entry.Result.StartsWith("跳过"))skipped++;else success++;}catch(Exception ex){entry.Result="失败";failed++;Log(entry.Method+" "+entry.Path+"："+ex.Message);}Get<DataGrid>("Apis").Items.Refresh();}current.LastUpload=DateTime.Now.ToString("yyyy-MM-dd HH:mm");current.LastResult="成功 "+success+" / 跳过 "+skipped+" / 失败 "+failed;current.SelectedKeys=selected.Select(x=>x.Key).ToList();Save();Log(current.LastResult);}
}


